{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace Table MapleMonk.MBO_Sales_Consolidated as WITH Payments AS ( SELECT CAST(CAST(id AS INT64) AS STRING) AS id, STRING_AGG(DISTINCT SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Type\') AS STRING), \', \') AS payment_types, SUM(SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Amount\') AS FLOAT64)) AS total_payment_amount, STRING_AGG(DISTINCT SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Id\') AS STRING), \', \') AS payment_ids, STRING_AGG(DISTINCT CAST(SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Method\') AS INT64) AS STRING), \', \') AS payment_methods, STRING_AGG(DISTINCT SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Notes\') AS STRING), \', \') AS payment_notes, STRING_AGG(DISTINCT SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.TransactionId\') AS STRING), \', \') AS transaction_ids FROM `MapleMonk.KA_DB_get_sales` s LEFT JOIN UNNEST(s.payments) AS item_json WHERE SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.TransactionId\') AS STRING) IS NOT NULL GROUP BY CAST(CAST(id AS INT64) AS STRING) ) SELECT SAFE_CAST(s.Id AS STRING) AS Order_Id, SAFE_CAST(s.ClientId AS STRING) AS client_id, DATETIME(TIMESTAMP(SAFE_CAST(s.SaleDateTime AS TIMESTAMP)), \'America/Los_Angeles\') AS sale_datetime, SAFE_CAST(s.LocationId AS STRING) AS location_id, SAFE_CAST(s.SalesRepId AS STRING) AS sales_rep_id, DATETIME(TIMESTAMP(SAFE_CAST(s.OriginalSaleDateTime AS TIMESTAMP)), \'America/Los_Angeles\') AS original_sale_datetime, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Id\') AS STRING) AS item_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.SaleDetailId\') AS STRING) AS sale_detail_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.CategoryId\') AS INT64) AS category_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.SubCategoryId\') AS INT64) AS subcategory_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Description\') AS STRING) AS item_description, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Quantity\') AS INT64) AS quantity, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.UnitPrice\') AS FLOAT64) AS unit_price, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.TotalAmount\') AS FLOAT64) AS total_amount, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.TaxAmount\') AS FLOAT64) AS tax_amount, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.DiscountAmount\') AS FLOAT64) AS discount_amount, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.DiscountPercent\') AS FLOAT64) AS discount_percent, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.PaymentRefId\') AS STRING) AS payment_ref_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.ContractId\') AS STRING) AS contract_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.BarcodeId\') AS STRING) AS barcode_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.GiftCardBarcodeId\') AS STRING) AS giftcard_barcode_id, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Returned\') AS BOOL) AS is_returned, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.IsService\') AS BOOL) AS is_service, (SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.ActiveDate\') AS TIMESTAMP)) AS active_date, (SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.ExpDate\') AS TIMESTAMP)) AS exp_date, SAFE_CAST(JSON_EXTRACT_SCALAR(item_json, \'$.Notes\') AS STRING) AS notes, p.payment_types, p.total_payment_amount, p.payment_ids, p.payment_methods, p.payment_notes, p.transaction_ids FROM `MapleMonk.KA_DB_get_sales` s LEFT JOIN UNNEST(s.PurchasedItems) AS item_json LEFT JOIN Payments p ON CAST(s.Id AS STRING) = p.id; Create Or Replace Table MapleMonk.MBO_Inventory_Consolidated as select MaxLevel, BarcodeId, CAST(CAST(ProductId AS INT64) AS STRING) ProductId, cast(UnitsSold as float64) as UnitsSold, CAST(CAST(LocationId AS INT64) AS STRING) as LocationId, cast(UnitsLogged as float64) as UnitsLogged, cast(ReorderLevel as float64) as ReorderLevel, cast(UnitsInStock as float64) as UnitsInStock, cast(DATETIME(_airbyte_normalized_at,\'America/Los_Angeles\') as date) AS Date from maplemonk.ka_DB_get_product_inventory qualify row_number() over(partition by CAST(CAST(ProductId AS INT64) AS STRING) ,CAST(CAST(LocationId AS INT64) AS STRING) , cast(DATETIME(_airbyte_normalized_at, \'America/Los_Angeles\') as date) order by DATETIME(_airbyte_normalized_at,\'America/Los_Angeles\') asc) = 1 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            